QUESTIONS.push({"id": "sjt-100", "d": "sjt", "lv": 2, "fr": "Un partenaire offre un cadeau coûteux pendant une sélection. Que faire ?", "o": ["Accepter puis le partager", "Refuser et suivre la procédure de déclaration", "Accepter si personne ne voit", "Reporter la sélection sans explication"], "a": 1, "x": "Préserver l’indépendance et déclarer selon les règles évite un conflit réel ou apparent.", "source": null});
QUESTIONS.push({"id": "sjt-101", "d": "sjt", "lv": 2, "fr": "Un fichier confidentiel a été envoyé au mauvais destinataire. Première réponse ?", "o": ["Effacer son propre message et se taire", "Signaler rapidement par le canal prévu et limiter l’exposition", "Attendre le rapport annuel", "Publier une capture"], "a": 1, "x": "Il faut contenir et signaler l’incident, sans le dissimuler ni amplifier la fuite.", "source": null});
