QUESTIONS.push({"id": "sjt-103", "d": "sjt", "lv": 2, "fr": "Un collègue n’a pas livré sa partie. Avant d’escalader un retard ordinaire :", "o": ["Clarifier le blocage et convenir d’un rattrapage", "L’accuser dans un message collectif", "Réécrire son évaluation annuelle", "Cesser toute communication"], "a": 0, "x": "La coordination directe permet souvent de résoudre un problème courant ; escalader si le risque persiste.", "source": null});
QUESTIONS.push({"id": "sjt-104", "d": "sjt", "lv": 2, "fr": "Lors d’une visite, un danger immédiat menace des travailleurs. Priorité ?", "o": ["Finir les photos", "Alerter les responsables de sécurité et faire appliquer les mesures urgentes adaptées", "Attendre la prochaine réunion mensuelle", "Éviter de documenter"], "a": 1, "x": "La protection immédiate des personnes prime, en utilisant les responsabilités et canaux appropriés.", "source": null});
