QUESTIONS.push({"id": "sjt-107", "d": "sjt", "lv": 2, "fr": "Une demande dépasse votre expertise. Quelle réponse est la plus utile ?", "o": ["Inventer une réponse plausible", "Clarifier le besoin et mobiliser un expert avec un délai convenu", "Ignorer la demande", "Promettre une validation immédiate"], "a": 1, "x": "Reconnaître une limite et chercher l’expertise protège la qualité sans abandonner le besoin.", "source": null});
QUESTIONS.push({"id": "sjt-108", "d": "sjt", "lv": 2, "fr": "Vous constatez une erreur dans un rapport déjà envoyé. Que faire ?", "o": ["Corriger la copie locale seulement", "Informer les destinataires concernés avec une correction traçable", "Attendre qu’on la découvre", "Accuser un collègue sans vérifier"], "a": 1, "x": "La correction doit atteindre ceux qui pourraient utiliser l’information erronée.", "source": null});
