QUESTIONS.push({"id": "sjt-110", "d": "sjt", "lv": 2, "fr": "Un collègue junior propose une idée contraire à la vôtre. Réponse adaptée ?", "o": ["L’écarter selon son ancienneté", "Tester les arguments selon les mêmes critères", "Accepter automatiquement", "Lui retirer la parole"], "a": 1, "x": "L’évaluation des idées doit reposer sur les faits et non sur le statut.", "source": null});
